solution.solution.cpp:
#include <cstdint>
#include <map>
#include <optional>
#include <string>
#include <vector>

using Memory = std::map<std::uint64_t, std::uint64_t>;

int slotOf(std::uint32_t displacement) { return static_cast<int>(displacement / 8); }

static std::optional<std::uint64_t> read(const Memory& m, std::uint64_t address)
{
    const auto it{ m.find(address) };
    if (it == m.end()) return std::nullopt;
    return it->second;
}

std::optional<std::uint64_t> virtualTarget(const Memory& m, std::uint64_t object, std::uint32_t displacement)
{
    const auto vtable{ read(m, object) };
    if (!vtable || *vtable == 0) return std::nullopt;
    return read(m, *vtable + displacement);
}

std::optional<std::string> classOf(const Memory& m, const std::map<std::uint64_t, std::string>& locators, std::uint64_t object)
{
    const auto vtable{ read(m, object) };
    if (!vtable || *vtable < 8) return std::nullopt;
    const auto locator{ read(m, *vtable - 8) };
    if (!locator) return std::nullopt;
    const auto it{ locators.find(*locator) };
    if (it == locators.end()) return std::nullopt;
    return it->second;
}

std::string undecorate(const std::string& name)
{
    if (name.empty() || name[0] != '?') return name;
    std::size_t at{ 1 };
    int special{ -1 };
    if (name.size() > 2 && name[1] == '?' && (name[2] == '0' || name[2] == '1')) { special = name[2] - '0'; at = 3; }
    const std::size_t stop{ name.find("@@", at) };
    if (stop == std::string::npos) return name;
    std::vector<std::string> parts;
    std::size_t start{ at };
    for (std::size_t i{ at }; i <= stop; ++i)
        if (name[i] == '@') { parts.push_back(name.substr(start, i - start)); start = i + 1; }
    std::string qualified;
    for (std::size_t i{ parts.size() }; i-- > 0;) qualified += parts[i] + (i ? "::" : "");
    if (special == 0) qualified += "::" + parts[0];
    if (special == 1) qualified += "::~" + parts[0];
    return qualified;
}

unitTests:
// An Archer object at 0x5000 whose vtable is at 0x140003000; its locator (at vtable - 8) is 0x140004100.
static Memory memory()
{
    return {
        { 0x5000, 0x140003000 }, { 0x5008, 100 },
        { 0x140002FF8, 0x140004100 },
        { 0x140003000, 0x140001100 }, { 0x140003008, 0x140001180 }, { 0x140003010, 0x140001200 }, { 0x140003018, 0x140001290 },
        { 0x6000, 0 },
    };
}

TEST("slots") {
    CHECK_EQ(slotOf(0x18), 3);
    CHECK_EQ(slotOf(0), 0);
    CHECK_EQ(slotOf(0x40), 8);
}
TEST("virtual call targets") {
    const Memory m{ memory() };
    CHECK_EQ(virtualTarget(m, 0x5000, 0x18).value_or(0), 0x140001290ull);
    CHECK_EQ(virtualTarget(m, 0x5000, 0x00).value_or(0), 0x140001100ull);
    CHECK(!virtualTarget(m, 0x5000, 0x20).has_value());
    CHECK(!virtualTarget(m, 0x6000, 0x00).has_value());
    CHECK(!virtualTarget(m, 0x7000, 0x00).has_value());
}
TEST("class names from the locator") {
    const Memory m{ memory() };
    const std::map<std::uint64_t, std::string> locators{ { 0x140004100, "Archer" }, { 0x140004200, "Unit" } };
    CHECK_EQ(classOf(m, locators, 0x5000).value_or("?"), std::string("Archer"));
    CHECK(!classOf(m, locators, 0x6000).has_value());
    CHECK(!classOf(m, {}, 0x5000).has_value());
}
TEST("undecorating names") {
    CHECK_EQ(undecorate("?update@Player@@QEAAXM@Z"), std::string("Player::update"));
    CHECK_EQ(undecorate("?attack@Enemy@Game@@QEAAHH@Z"), std::string("Game::Enemy::attack"));
    CHECK_EQ(undecorate("??0Player@@QEAA@XZ"), std::string("Player::Player"));
    CHECK_EQ(undecorate("??1Unit@Game@@UEAA@XZ"), std::string("Game::Unit::~Unit"));
    CHECK_EQ(undecorate("?gScore@@3HA"), std::string("gScore"));
    CHECK_EQ(undecorate("CreateFileW"), std::string("CreateFileW"));
}

